mapper.select:
SELECT wbi.word_id
FROM word_book_item wbi
WHERE wbi.book_id = #{bookId}
  AND NOT EXISTS (
    SELECT 1
    FROM student_word_progress p
    WHERE p.student_id = #{studentId}
      AND p.word_id = wbi.word_id
  )
ORDER BY wbi.week IS NULL, wbi.week ASC,
         wbi.unit_name IS NULL, wbi.unit_name ASC,
         wbi.sort_order ASC, wbi.id ASC
LIMIT #{limit}
